    const ctx = {
        capabilities,
        workspacePolicy: REPO_WORKSPACE_POLICY,
        toolHandlers: {
            handleSearchCode: async (args: Record<string, unknown>) => {
                calls.push(args);
                return {
                    content: [{ type: 'text' as const, text: JSON.stringify({
                        formatVersion: 2,
                        status: 'ok',
                        path: '/repo',
                        codebaseRoot: '/repo',
                        query: 'auth',
                        scope: 'runtime',
                        groupBy: 'symbol',
                        resultMode: 'grouped',
                        limit: 3,
                        freshnessDecision: { mode: 'skipped_recent' },
