});","repository_relative_path":"packages/mcp/src/tools/search_codebase.test.ts","signature_or_declaration":"test('search_codebase accepts bounded diagnostic candidate depth only with full diagnostics', async () => {","source_references":[],"structural_context":{"direct_callees":[],"direct_callers":[],"supporting_tests":[]},"symbol_kind":"function"}

