{"candidate_role":"test","canonical_symbol_label":"function test("search_codebase denies an unauthorized root in grouped mode without running the handler") callback","query_relevant_source_excerpt":"test('search_codebase denies an unauthorized root in grouped mode without running the handler', async () => {
    const rootA = fs.mkdtempSync(path.join(os.tmpdir(), 'search-codebase-auth-a-'));
    const rootB = fs.mkdtempSync(path.join(os.tmpdir(), 'search-codebase-auth-b-'));
    try {
        const capabilities = new CapabilityResolver(buildConfig());
        let handlerRan = false;
        const ctx = {
            capabilities,
            workspacePolicy: buildWorkspacePolicy([rootA]),
            toolHandlers: {
                handleSearchCode: async () => {
                    handlerRan = true;
                    throw new Error('handler must not run for an unauthorized path');
                },
            },
        } as unknown as ToolContext;

        const telemetry = await captureTelemetry(async () => {
            const response = await searchCodebaseTool.execute({
                path: rootB,
                query: 'auth',
                resultMode: 'grouped',
            }, ctx);
            const payload = JSON.parse(response.content[0].text);

            assert.equal(response.isError, true);
            assert.equal(payload.status, 'error');
            assert.equal(payload.code, 'ROOT_NOT_AUTHORIZED');
            assert.equal(payload.reason, 'root_not_authorized');
            assert.equal(payload.path, rootB);
            assert.equal(typeof payload.message, 'string');
        });

        assert.equal(handlerRan, false);
        // The gate precedes telemetry: a denied search emits no [TELEMETRY] line.
        assert.equal(telemetry.length, 0);
    } finally {
        fs.rmSync(rootA, { recursive: true, force: true });
        fs.rmSync(rootB, { recursive: true, force: true });
    }
});","repository_relative_path":"packages/mcp/src/tools/search_codebase.test.ts","signature_or_declaration":"test('search_codebase denies an unauthorized root in grouped mode without running the handler', async () => {","source_references":[],"structural_context":{"direct_callees":[{"canonical_symbol_label":"constructor constructor","relation":"callee","repository_relative_path":"packages/mcp/src/core/capabilities.ts"},{"canonical_symbol_label":"function buildConfig","relation":"callee","repository_relative_path":"packages/mcp/src/tools/search_codebase.test.ts"},{"canonical_symbol_label":"function buildWorkspacePolicy","relation":"callee","repository_relative_path":"packages/mcp/src/tools/search_codebase.test.ts"}],"direct_callers":[],"supporting_tests":[]},"symbol_kind":"function"}

